    'roster.deidentified': 'Anonymisiert', 'roster.real_local_only': 'Nur lokale Nutzung. Nicht veröffentlichen oder außerhalb des Studienteams teilen.', 'roster.gcsf_d14': 'G-CSF nach D+14', 'roster.toci': 'Tocilizumab', 'roster.crs3': 'CRS-Grad ≥ 3', 'roster.max_crs': 'Max. CRS', 'roster.last_lab': 'Letztes Labor', 'roster.flag_only': 'nur ja/nein, ohne Datum', 'roster.model_fit_real': 'Modell an D+28',
